#ifndef DDS_TABLES_H
#define DDS_TABLES_H

#include <stdint.h>

#define DDS_SINE_BITS    8u
#define DDS_SINE_POINTS  (1u << DDS_SINE_BITS)

/** sin(2*pi*k/256) in Q15 for k = 0..256 (entry 256 repeats entry 0). */
extern const int16_t dds_sine_table[DDS_SINE_POINTS + 1];

#endif /* DDS_TABLES_H */
